// AndWith convenience method for combining two or more filters with AND statement
func (f *ProductFilterType) AndWith(f2 ...*ProductFilterType) *ProductFilterType {
	_f2 := CompactNils(f2)
	if len(_f2) == 0 {
		return f
	}
	return &ProductFilterType{
		And: append(_f2, f),
	}
}

// OrWith convenience method for combining two or more filters with OR statement
func (f *ProductFilterType) OrWith(f2 ...*ProductFilterType) *ProductFilterType {
	_f2 := CompactNils(f2)
	if len(_f2) == 0 {
		return f
	}
	return &ProductFilterType{
		Or: append(_f2, f),
	}
}

func (f *ProductSkuFilterType) IsEmpty(ctx context.Context) bool {
	wheres := []string{}
	values := []interface{}{}
	joins := []string{}
	err := f.ApplyWithAlias(ctx, "companies", &wheres, &values, &joins)
	if err != nil {
		panic(err)
	}
	return len(wheres) == 0
}
func (f *ProductSkuFilterType) Apply(ctx context.Context, wheres *[]string, values *[]interface{}, joins *[]string) error {
	return f.ApplyWithAlias(ctx, TableName("product_skus", ctx), wheres, values, joins)
}
func (f *ProductSkuFilterType) ApplyWithAlias(ctx context.Context, alias string, wheres *[]string, values *[]interface{}, joins *[]string) error {
	if f == nil {
		return nil
	}
	aliasPrefix := alias + "."

	_where, _values := f.WhereContent(aliasPrefix)
	*wheres = append(*wheres, _where...)
	*values = append(*values, _values...)

	if f.Or != nil {
		cs := []string{}
		vs := []interface{}{}
		js := []string{}
		for _, or := range f.Or {
			_cs := []string{}
			err := or.ApplyWithAlias(ctx, alias, &_cs, &vs, &js)
			if err != nil {
				return err
			}
			cs = append(cs, strings.Join(_cs, " AND "))
		}
		if len(cs) > 0 {
			*wheres = append(*wheres, "("+strings.Join(cs, " OR ")+")")
		}
		*values = append(*values, vs...)
		*joins = append(*joins, js...)
	}
	if f.And != nil {
		cs := []string{}
		vs := []interface{}{}
		js := []string{}
		for _, and := range f.And {
			err := and.ApplyWithAlias(ctx, alias, &cs, &vs, &js)
			if err != nil {
				return err
			}
		}
		if len(cs) > 0 {
			*wheres = append(*wheres, strings.Join(cs, " AND "))
		}
		*values = append(*values, vs...)
		*joins = append(*joins, js...)
	}

	if f.Product != nil {
		_alias := alias + "_product"
		*joins = append(*joins, "LEFT JOIN "+TableName("products", ctx)+" "+_alias+" ON "+_alias+".id = "+alias+"."+"product_id")
		err := f.Product.ApplyWithAlias(ctx, _alias, wheres, values, joins)
		if err != nil {
			return err
		}
	}

	if f.SpecificationValues != nil {
		_alias := alias + "_specificationValues"
		*joins = append(*joins, "LEFT JOIN "+TableName("product_sku_specification_values", ctx)+" "+_alias+" ON "+_alias+"."+"sku_id"+" = "+alias+".id")
		err := f.SpecificationValues.ApplyWithAlias(ctx, _alias, wheres, values, joins)
		if err != nil {
			return err
		}
	}

	if f.Packages != nil {
		_alias := alias + "_packages"
		*joins = append(*joins, "LEFT JOIN "+TableName("product_packages", ctx)+" "+_alias+" ON "+_alias+"."+"sku_id"+" = "+alias+".id")
		err := f.Packages.ApplyWithAlias(ctx, _alias, wheres, values, joins)
		if err != nil {
			return err
		}
	}

	if f.Listings != nil {
		_alias := alias + "_listings"
		*joins = append(*joins, "LEFT JOIN "+TableName("store_listings", ctx)+" "+_alias+" ON "+_alias+"."+"sku_id"+" = "+alias+".id")
		err := f.Listings.ApplyWithAlias(ctx, _alias, wheres, values, joins)
		if err != nil {
			return err
		}
	}

	return nil
}

