// AndWith convenience method for combining two or more filters with AND statement
func (f *SpecificationDefinitionFilterType) AndWith(f2 ...*SpecificationDefinitionFilterType) *SpecificationDefinitionFilterType {
	_f2 := CompactNils(f2)
	if len(_f2) == 0 {
		return f
	}
	return &SpecificationDefinitionFilterType{
		And: append(_f2, f),
	}
}

// OrWith convenience method for combining two or more filters with OR statement
func (f *SpecificationDefinitionFilterType) OrWith(f2 ...*SpecificationDefinitionFilterType) *SpecificationDefinitionFilterType {
	_f2 := CompactNils(f2)
	if len(_f2) == 0 {
		return f
	}
	return &SpecificationDefinitionFilterType{
		Or: append(_f2, f),
	}
}

func (f *SpecificationValueFilterType) IsEmpty(ctx context.Context) bool {
	wheres := []string{}
	values := []interface{}{}
	joins := []string{}
	err := f.ApplyWithAlias(ctx, "companies", &wheres, &values, &joins)
	if err != nil {
		panic(err)
	}
	return len(wheres) == 0
}
func (f *SpecificationValueFilterType) Apply(ctx context.Context, wheres *[]string, values *[]interface{}, joins *[]string) error {
	return f.ApplyWithAlias(ctx, TableName("specification_values", ctx), wheres, values, joins)
}
func (f *SpecificationValueFilterType) ApplyWithAlias(ctx context.Context, alias string, wheres *[]string, values *[]interface{}, joins *[]string) error {
	if f == nil {
		return nil
	}
	aliasPrefix := alias + "."

	_where, _values := f.WhereContent(aliasPrefix)
	*wheres = append(*wheres, _where...)
	*values = append(*values, _values...)

	if f.Or != nil {
		cs := []string{}
		vs := []interface{}{}
		js := []string{}
		for _, or := range f.Or {
			_cs := []string{}
			err := or.ApplyWithAlias(ctx, alias, &_cs, &vs, &js)
			if err != nil {
				return err
			}
			cs = append(cs, strings.Join(_cs, " AND "))
		}
		if len(cs) > 0 {
			*wheres = append(*wheres, "("+strings.Join(cs, " OR ")+")")
		}
		*values = append(*values, vs...)
		*joins = append(*joins, js...)
	}
	if f.And != nil {
		cs := []string{}
		vs := []interface{}{}
		js := []string{}
		for _, and := range f.And {
			err := and.ApplyWithAlias(ctx, alias, &cs, &vs, &js)
			if err != nil {
				return err
			}
		}
		if len(cs) > 0 {
			*wheres = append(*wheres, strings.Join(cs, " AND "))
		}
		*values = append(*values, vs...)
		*joins = append(*joins, js...)
	}

	if f.Specification != nil {
		_alias := alias + "_specification"
		*joins = append(*joins, "LEFT JOIN "+TableName("specification_definitions", ctx)+" "+_alias+" ON "+_alias+".id = "+alias+"."+"specification_id")
		err := f.Specification.ApplyWithAlias(ctx, _alias, wheres, values, joins)
		if err != nil {
			return err
		}
	}

	if f.ProductChoices != nil {
		_alias := alias + "_productChoices"
		*joins = append(*joins, "LEFT JOIN "+TableName("product_specification_choices", ctx)+" "+_alias+" ON "+_alias+"."+"value_id"+" = "+alias+".id")
		err := f.ProductChoices.ApplyWithAlias(ctx, _alias, wheres, values, joins)
		if err != nil {
			return err
		}
	}

	if f.SkuValues != nil {
		_alias := alias + "_skuValues"
		*joins = append(*joins, "LEFT JOIN "+TableName("product_sku_specification_values", ctx)+" "+_alias+" ON "+_alias+"."+"value_id"+" = "+alias+".id")
		err := f.SkuValues.ApplyWithAlias(ctx, _alias, wheres, values, joins)
		if err != nil {
			return err
		}
	}

	return nil
}

