func (f *StoreListingFilterType) ApplyWithAlias(ctx context.Context, alias string, wheres *[]string, values *[]interface{}, joins *[]string) error {
	if f == nil {
		return nil
	}
	aliasPrefix := alias + "."

	_where, _values := f.WhereContent(aliasPrefix)
	*wheres = append(*wheres, _where...)
	*values = append(*values, _values...)

	if f.Or != nil {
		cs := []string{}
		vs := []interface{}{}
		js := []string{}
		for _, or := range f.Or {
			_cs := []string{}
			err := or.ApplyWithAlias(ctx, alias, &_cs, &vs, &js)
			if err != nil {
				return err
			}
			cs = append(cs, strings.Join(_cs, " AND "))
		}
		if len(cs) > 0 {
			*wheres = append(*wheres, "("+strings.Join(cs, " OR ")+")")
		}
		*values = append(*values, vs...)
		*joins = append(*joins, js...)
	}
	if f.And != nil {
		cs := []string{}
		vs := []interface{}{}
		js := []string{}
		for _, and := range f.And {
			err := and.ApplyWithAlias(ctx, alias, &cs, &vs, &js)
			if err != nil {
				return err
			}
		}
		if len(cs) > 0 {
			*wheres = append(*wheres, strings.Join(cs, " AND "))
		}
		*values = append(*values, vs...)
		*joins = append(*joins, js...)
	}

	if f.Store != nil {
		_alias := alias + "_store"
		*joins = append(*joins, "LEFT JOIN "+TableName("stores", ctx)+" "+_alias+" ON "+_alias+".id = "+alias+"."+"store_id")
		err := f.Store.ApplyWithAlias(ctx, _alias, wheres, values, joins)
		if err != nil {
			return err
		}
	}

	if f.Sku != nil {
		_alias := alias + "_sku"
		*joins = append(*joins, "LEFT JOIN "+TableName("product_skus", ctx)+" "+_alias+" ON "+_alias+".id = "+alias+"."+"sku_id")
		err := f.Sku.ApplyWithAlias(ctx, _alias, wheres, values, joins)
		if err != nil {
			return err
		}
	}

	if f.Offers != nil {
		_alias := alias + "_offers"
		*joins = append(*joins, "LEFT JOIN "+TableName("store_package_offers", ctx)+" "+_alias+" ON "+_alias+"."+"listing_id"+" = "+alias+".id")
		err := f.Offers.ApplyWithAlias(ctx, _alias, wheres, values, joins)
		if err != nil {
			return err
		}
	}

	if f.Batches != nil {
		_alias := alias + "_batches"
		*joins = append(*joins, "LEFT JOIN "+TableName("store_inventory_batches", ctx)+" "+_alias+" ON "+_alias+"."+"listing_id"+" = "+alias+".id")
		err := f.Batches.ApplyWithAlias(ctx, _alias, wheres, values, joins)
		if err != nil {
			return err
		}
	}

	return nil
}

