func (f *StorePackageOfferFilterType) Apply(ctx context.Context, wheres *[]string, values *[]interface{}, joins *[]string) error {
	return f.ApplyWithAlias(ctx, TableName("store_package_offers", ctx), wheres, values, joins)
}
func (f *StorePackageOfferFilterType) ApplyWithAlias(ctx context.Context, alias string, wheres *[]string, values *[]interface{}, joins *[]string) error {
	if f == nil {
		return nil
	}
	aliasPrefix := alias + "."

	_where, _values := f.WhereContent(aliasPrefix)
	*wheres = append(*wheres, _where...)
	*values = append(*values, _values...)

	if f.Or != nil {
		cs := []string{}
		vs := []interface{}{}
		js := []string{}
		for _, or := range f.Or {
			_cs := []string{}
			err := or.ApplyWithAlias(ctx, alias, &_cs, &vs, &js)
			if err != nil {
				return err
			}
			cs = append(cs, strings.Join(_cs, " AND "))
		}
		if len(cs) > 0 {
			*wheres = append(*wheres, "("+strings.Join(cs, " OR ")+")")
		}
		*values = append(*values, vs...)
		*joins = append(*joins, js...)
	}
	if f.And != nil {
		cs := []string{}
		vs := []interface{}{}
		js := []string{}
		for _, and := range f.And {
			err := and.ApplyWithAlias(ctx, alias, &cs, &vs, &js)
			if err != nil {
				return err
			}
		}
		if len(cs) > 0 {
			*wheres = append(*wheres, strings.Join(cs, " AND "))
		}
		*values = append(*values, vs...)
		*joins = append(*joins, js...)
	}

	if f.Listing != nil {
		_alias := alias + "_listing"
		*joins = append(*joins, "LEFT JOIN "+TableName("store_listings", ctx)+" "+_alias+" ON "+_alias+".id = "+alias+"."+"listing_id")
		err := f.Listing.ApplyWithAlias(ctx, _alias, wheres, values, joins)
		if err != nil {
			return err
		}
	}

	if f.Package != nil {
		_alias := alias + "_package"
		*joins = append(*joins, "LEFT JOIN "+TableName("product_packages", ctx)+" "+_alias+" ON "+_alias+".id = "+alias+"."+"package_id")
		err := f.Package.ApplyWithAlias(ctx, _alias, wheres, values, joins)
		if err != nil {
			return err
		}
	}

	if f.PriceRevisions != nil {
		_alias := alias + "_priceRevisions"
		*joins = append(*joins, "LEFT JOIN "+TableName("store_price_revisions", ctx)+" "+_alias+" ON "+_alias+"."+"offer_id"+" = "+alias+".id")
		err := f.PriceRevisions.ApplyWithAlias(ctx, _alias, wheres, values, joins)
		if err != nil {
			return err
		}
	}

	if f.PromotionTargets != nil {
		_alias := alias + "_promotionTargets"
		*joins = append(*joins, "LEFT JOIN "+TableName("store_promotion_targets", ctx)+" "+_alias+" ON "+_alias+"."+"offer_id"+" = "+alias+".id")
		err := f.PromotionTargets.ApplyWithAlias(ctx, _alias, wheres, values, joins)
		if err != nil {
			return err
		}
	}

	return nil
}

